/// <summary>
/// MPJ_26540_PriceSimulatorChanges
/// METUnitOfMeasureConversion_OnClicked
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormControlEventHandler(formControlStr(RetailPricingSimulator, METUnitOfMeasureConversion), FormControlEventType::Clicked)]
public static void METUnitOfMeasureConversion_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormRun fr = sender.formRun();
    RetailPricingSimulatorSalesLine simSalesLine = fr.dataHelper().FindDataSource(formDataSourceStr(RetailPricingSimulator, RetailPricingSimulatorSalesLine)).cursor();
    if(simSalesLine && simSalesLine.Product)
    {
        Args args = new Args();
        args.record(EcoResProduct::find(simSalesLine.Product));
        args.menuItemName(menuItemDisplayStr(UnitOfMeasureConversion));
        new MenuFunction(menuItemDisplayStr(UnitOfMeasureConversion), MenuItemType::Display).run(args);
    }
}
